const vol3Dialogues = {
  // BÀI 51: 亡羊补牢
  "jc_3_1_51": [
    { ...chars.wang, sectionTitle: "课文一：成语典故 (Điển cố Thành ngữ: Mất bò mới lo làm chuồng)", hanzi: "从前有个人养了一群羊。一天早晨，他发现少了一只羊，原来羊圈破了个窟窿，夜里狼钻进来把羊叼走了。", pinyin: "Cóngqián yǒu gè rén yǎng le yì qún yáng. Yì tiān zǎochen, tā fāxiàn shǎo le yì zhī yáng, yuánlái yángjuàn pò le gè kūlong, yèlǐ láng zuān jìnlái bǎ yáng diāozǒu le.", vi: "Ngày xưa có một người nuôi một bầy cừu. Một buổi sáng, anh ta phát hiện thiếu mất một con, thì ra chuồng cừu bị thủng một lỗ, ban đêm chó sói chui vào tha cừu đi mất." },
    { ...chars.zhang, hanzi: "邻居劝他说：“赶紧把羊圈修好吧，堵上那个窟窿。”那个人却说：“羊已经丢了，还修羊圈干什么？”", pinyin: "Línjū quàn tā shuō: \"Gǎnjǐn bǎ yángjuàn xiūhǎo ba, dǔshang nà ge kūlong.\" Nà ge rén què shuō: \"Yáng yǐjīng diū le, hái xiū yángjuàn gàn shénme?\"", vi: "Người hàng xóm khuyên anh ta: \"Mau sửa lại chuồng cừu đi, bịt cái lỗ thủng đó lại.\" Anh ta lại bảo: \"Cừu mất rồi, còn sửa chuồng làm gì nữa?\"" },
    { ...chars.wang, hanzi: "结果第二天夜里，狼又钻进羊圈，又叼走了一只羊。他非常后悔，赶紧把羊圈修得结结实实的。从此以后，他的羊再也没丢过。", pinyin: "Jiéguǒ dì-èr tiān yèlǐ, láng yòu zuān jìn yángjuàn, yòu diāozǒu le yì zhī yáng. Tā fēicháng hòuhuǐ, gǎnjǐn bǎ yángjuàn xiū de jiējiē-shíshí de. Cóngcǐ yǐhòu, tā de yáng zài yě méi diūguo.", vi: "Kết quả đêm hôm sau, chó sói lại chui vào chuồng cừu tha đi một con nữa. Anh ta vô cùng ân hận, vội vàng sửa sang lại chuồng cừu thật kiên cố chắc chắn. Từ đó về sau, cừu của anh ta không bao giờ bị mất nữa." },
    { ...chars.mary, sectionTitle: "课文二：现代哲理启示 (Ý nghĩa triết lý hiện đại)", hanzi: "老师，这则寓言告诉我们：出了问题并不可怕，只要及时想办法补救，就能防止造成更大的损失，对吗？", pinyin: "Lǎoshī, zhè zé yùyán gàosu wǒmen: chū le wèntí bìng bù kěpà, zhǐyào jíshí xiǎng bànfǎ bǔjiù, jiù néng fángzhǐ zàochéng gèng dà de sǔnshī, duì ma?", vi: "Thưa thầy, câu ngụ ngôn này dạy chúng ta: Gặp sai sót không đáng sợ, chỉ cần kịp thời nghĩ cách bù đắp sửa chữa thì sẽ ngăn ngừa được tổn thất lớn hơn, có đúng không ạ?" },
    { ...chars.wang, hanzi: "完全正确！这就是成语“亡羊补牢，未为迟也”的精髓所在。", pinyin: "Wánquán zhèngquè! Zhè jiù shì chéngyǔ \"wáng yáng bǔ láo, wèi wéi chí yě\" de jīngsuǐ suǒzài.", vi: "Hoàn toàn chính xác! Đó chính là tinh hoa cốt lõi của câu thành ngữ \"Mất bò mới lo làm chuồng, vẫn chưa muộn màng\"." }
  ],

  // BÀI 52: 守株待兔
  "jc_3_1_52": [
    { ...chars.wang, sectionTitle: "课文一：寓言原著 (Điển cố: Ôm cây đợi thỏ)", hanzi: "宋国有个农夫，正在田里耕作。忽然一只兔子飞快地跑过来，不小心撞在田边的一棵大树桩上，折断了脖子死掉了。", pinyin: "Sòng guó yǒu gè nóngfū, zhèngzài tián lǐ gēngzuò. Hūrán yì zhī tùzi fēikuài de pǎo guòlai, bù xiǎoxīn zhuàng zài tiánbiān de yì kē dà shùzhuāng shàng, zhéduàn le bózǐ sǐdiào le.", vi: "Nước Tống có một bác nông dân đang cày cấy trên ruộng. Bỗng nhiên có một con thỏ chạy như bay tới, sơ ý đâm sầm vào gốc cây to bên bờ ruộng, gãy cổ chết tươi." },
    { ...chars.tian, hanzi: "农夫白白捡了一只又肥又大的兔子，心里美滋滋的。从此他放下了锄头，整天守在树桩旁，希望再有兔子撞上来。", pinyin: "Nóngfū báibái jiǎn le yì zhī yòu féi yòu dà de tùzi, xīnlǐ měizīzī de. Cóngcǐ tā fàngxià le chútou, zhěng tiān shǒu zài shùzhuāng páng, xīwàng zài yǒu tùzi zhuàng shànglai.", vi: "Bác nông dân không tốn một giọt mồ hôi mà nhặt được con thỏ vừa béo vừa to, trong lòng mừng rơn. Từ đó bỏ hẳn cày cuốc, suốt ngày ngồi canh bên gốc cây, mong lại có con thỏ khác đâm vào." },
    { ...chars.wang, hanzi: "日子一天天过去，他再也没等到撞死的兔子，而他的田地里长满了荒草，庄稼全荒芜了，他成了全天下人的笑柄。", pinyin: "Rìzi yì tiān tiān guòqu, tā zài yě méi děngdào zhuàngsǐ de tùzi, ér tā de tiándì lǐ zhǎngmǎn le huāngcǎo, zhuāngjia quán huāngwú le, tā chéng le quán tiānxià rén de xiàobǐng.", vi: "Ngày qua ngày, bác ta chẳng bao giờ đợi được con thỏ nào đâm đầu vào gốc cây nữa, trong khi ruộng đồng cỏ dại mọc um tùm, hoa màu héo úa hết, trở thành trò cười cho khắp thiên hạ." },
    { ...chars.mike, sectionTitle: "课文二：深度哲学讨论 (Thảo luận triết học)", hanzi: "这个成语讽刺了那些不想付出辛勤劳动，只想侥幸碰运气、妄想不劳而获的人，告诫我们唯有脚踏实地才是成功之道。", pinyin: "Zhè ge chéngyǔ fěngcì le nàxiē bù xiǎng fùchū xīnqín láodòng, zhǐ xiǎng jiǎoxìng pèng yùnqi, wàngxiǎng bù láo ér huò de rén, gàojiè wǒmen wéiyǒu jiǎotà-shídì cái shì chénggōng zhī dào.", vi: "Câu thành ngữ này châm biếm những kẻ không muốn bỏ công sức lao động chăm chỉ, chỉ mong may rủi, ảo tưởng không làm mà hưởng, răn dạy chúng ta chỉ có bước đi vững chãi thực tế mới là con đường dẫn tới thành công." }
  ],

  // BÀI 53: 塞翁失马
  "jc_3_1_53": [
    { ...chars.wang, sectionTitle: "课文一：祸福相依 (Phúc họa tương sinh: Tái ông mất ngựa)", hanzi: "靠近边塞的地方住着一位精通术数的老人。一天他的马无缘无故逃跑到了塞外的胡人领地，邻居都来安慰他。", pinyin: "Kàojìn biānsài de dìfang zhù zhe yí wèi jīngtōng shùshù de lǎorén. Yì tiān tā de mǎ wúyuán-wúgù táopǎo dào le sàiwài de Húrén lǐngdì, línjū dōu lái ānwèi tā.", vi: "Gần vùng biên ải có một ông lão tinh thông thuật dịch số. Một hôm ngựa của ông vô cớ chạy lạc sang lãnh địa người Hồ ngoài biên ải, hàng xóm đều đến an ủi ông." },
    { ...chars.zhang, hanzi: "老人却平静地说：“这怎么知道不会成为一件好事呢？”过了几个月，那匹马竟然带回了一匹胡人的骏马。", pinyin: "Lǎorén què píngjìng de shuō: \"Zhè zěnme zhīdào bú huì chéngwéi yí jiàn hǎoshì ne?\" Guò le jǐ gè yuè, nà pǐ mǎ jìngrán dài huí le yì pǐ Húrén de jùnmǎ.", vi: "Ông lão lại điềm tĩnh nói: \"Biết đâu việc này chẳng trở thành điều tốt lành thì sao?\" Mấy tháng sau, con ngựa nọ chẳng những quay về mà còn dẫn theo một con tuấn mã của người Hồ." },
    { ...chars.wang, hanzi: "邻居又来祝贺，老人又说：“这怎么知道不会招来祸患呢？”老人的儿子酷爱骑马，结果摔断了大腿，成了瘸子。", pinyin: "Línjū yòu lái zhùhè, lǎorén yòu shuō: \"Zhè zěnme zhīdào bú huì zhāolái huòhuàn ne?\" Lǎorén de érzi kù'ài qí mǎ, jiéguǒ shuāiduàn le dàtuǐ, chéng le quézi.", vi: "Hàng xóm lại sang chúc mừng, ông lão lại bảo: \"Biết đâu việc này chẳng rước lấy tai họa?\" Con trai ông lão mê cưỡi tuấn mã, kết quả bị ngã gãy đùi, trở thành tàn tật." },
    { ...chars.edward, sectionTitle: "课文二：辩证法则 (Quy luật biện chứng nhân sinh)", hanzi: "一年后胡人发兵大举入侵，青年男子全被征召参军打仗，十有八九阵亡，老人的儿子因腿瘸免征，父子俩得以保全性命！", pinyin: "Yì nián hòu Húrén fābīng dàjǔ rùqīn, qīngnián nánzǐ quán bèi zhēngzhào cānjūn dǎzhàng, shí yǒu bājiǔ zhènwáng, lǎorén de érzi yīn tuǐ qué miǎozhēng, fùzǐ liǎ déyǐ bǎoquán xìngmìng!", vi: "Một năm sau người Hồ dấy binh xâm lược, thanh niên trai tráng đều bị bắt đi lính đánh trận, mười người chết đến tám chín, con trai ông lão vì chân thọt nên được miễn dịch, hai cha con nhờ đó giữ trọn mạng sống!" },
    { ...chars.mary, hanzi: "“塞翁失马，焉知非福”蕴含了中国古人深刻的辩证法智慧：坏事可以引出好结果，好事也可能潜藏隐患，我们要以平常心面对起伏。", pinyin: "\"Sài wēng shī mǎ, yān zhī fēi fú\" yùnhán le Zhōngguó gǔrén shēnkè de biànzhèngfǎ zhìhuì: huàishì kěyǐ yǐnchū hǎo jiéguǒ, hǎoshì yě kěnéng qiáncáng yǐnhuàn, wǒmen yào yǐ píngchángxīn miànduì qǐfú.", vi: "\"Tái ông mất ngựa, họa phúc khôn lường\" chứa đựng trí tuệ biện chứng sâu sắc của người Trung Hoa xưa: chuyện xấu có thể mang lại kết quả tốt, chuyện mừng cũng tiềm ẩn rủi ro, con người cần lấy tâm thế an nhiên để đối diện thăng trầm cuộc đời." }
  ],

  // BÀI 54: 狐假虎威
  "jc_3_1_54": [
    { ...chars.wang, sectionTitle: "课文一：森林之王与狡猾狐狸 (Chúa sơn lâm & Cáo giảo hoạt)", hanzi: "老虎寻找各种野兽吃，抓住了一只狡猾的狐狸。狐狸眼珠一转，傲慢地说：“你不敢吃我，天帝派我来做百兽的首领，你吃了我就是违抗天帝的命令！”", pinyin: "Lǎohǔ xúnzhǎo gèzhǒng yěshòu chī, zhuāzhù le yì zhī jiǎohuá de húli. Húli yǎnzhū yì zhuàn, àomàn de shuō: \"Nǐ bù gǎn chī wǒ, tiāndì pài wǒ lái zuò bǎishòu de shǒulǐng, nǐ chī le wǒ jiù shì wéikàng tiāndì de mìnglìng!\"", vi: "Hổ rình bắt các thú rừng để ăn thịt, tóm được một con cáo giảo hoạt. Cáo đảo mắt một vòng, kiêu ngạo nói: \"Ngươi không dám ăn thịt ta đâu, Thượng Đế phái ta xuống làm chúa tể muôn loài thú, ngươi ăn thịt ta là chống lại mệnh trời!\"" },
    { ...chars.tian, hanzi: "老虎半信半疑，狐狸便说：“你在我后面跟着，看哪只野兽见了我敢不逃跑！”老虎便跟着它走。百兽一见它们，无不吓得望风而逃。", pinyin: "Lǎohǔ bànxìn-bànyí, húli biàn shuō: \"Nǐ zài wǒ hòumiàn gēnzhe, kàn nǎ zhī yěshòu jiàn le wǒ gǎn bù táopǎo!\" Lǎohǔ biàn gēnzhe tā zǒu. Bǎishòu yí jiàn tāmen, wúbù xià de wàngfēng'értáo.", vi: "Hổ nửa tin nửa ngờ, cáo bèn bảo: \"Ngươi cứ đi sau lưng ta, xem có loài thú nào nhìn thấy ta mà không sợ chạy thục mạng!\" Hổ bèn đi sau nó. Muôn thú vừa thấy bóng dáng, không con nào là không hồn xiêu phách lạc cắm đầu bỏ chạy." },
    { ...chars.wang, hanzi: "老虎不知道百兽是害怕自己而逃跑，还以为真的是害怕狐狸呢！", pinyin: "Lǎohǔ bù zhīdào bǎishòu shì hàipà zìjǐ ér táopǎo, hái yǐwéi zhēnde shì hàipà húli ne!", vi: "Hổ chẳng hề hay biết muôn thú sợ hãi chính bản thân mình mà chạy, cứ ngỡ chúng thực sự khiếp sợ con cáo!" },
    { ...chars.mike, sectionTitle: "课文二：现代表述 (Liên hệ thực tiễn)", hanzi: "这篇寓言形象地讽刺了那些依仗别人的权势来欺压弱小、狐假虎威的恶劣行径，生动至极！", pinyin: "Zhè piān yùyán xíngxiàng de fěngcì le nàxiē yīzhàng biérén de quánshì lái qīyā ruòxiǎo, hú-jiǎ-hǔ-wēi de èliè xíngjìng, shēngdòng zhì jí!", vi: "Mẩu ngụ ngôn này châm biếm một cách hình tượng những kẻ dựa dẫm quyền thế của người khác để ức hiếp kẻ yếu, \"cáo mượn oai hùm\", vô cùng sống động!" }
  ],

  // BÀI 55: 画蛇添足
  "jc_3_1_55": [
    { ...chars.wang, sectionTitle: "课文一：楚人画蛇比赛 (Người nước Sở thi vẽ rắn)", hanzi: "古代楚国有一家祠堂祭祖，赐给办事人员一壶美酒。几个人商量：“这壶酒几个人喝不够，一个人喝正好，让我们在地上比赛画蛇，谁先画好谁就喝酒。”", pinyin: "Gǔdài Chǔ guó yǒu yì jiā cítáng jìzǔ, cìgěi bànshì rényuán yì hú měijiǔ. Jǐ gè rén shāngliang: \"Zhè hú jiǔ jǐ gè rén hē bú gòu, yí gè rén hē zhènghǎo, ràng wǒmen zài dìshang bǐsài huà shé, shéi xiān huà hǎo shéi jiù hē jiǔ.\"", vi: "Thời xưa nước Sở có một nhà cúng tế tổ tiên, ban thưởng cho đám người phụ việc một ấm rượu ngon. Mấy người bàn tính: \"Ấm rượu này mấy người uống thì không đủ, một người uống mới vừa, chúng ta hãy thi vẽ rắn dưới đất, ai vẽ xong trước thì được uống rượu.\"" },
    { ...chars.zhang, hanzi: "一个人很快把蛇画好了，拿起酒壶正准备喝，见别人还没画完，便左手拿着酒壶，右手得意地说：“我还能给蛇添上四只脚呢！”", pinyin: "Yí gè rén hěn kuài bǎ shé huà hǎo le, náqǐ jiǔhú zhèng zhǔnbèi hē, jiàn biérén hái méi huàwán, biàn zuǒshǒu ná zhe jiǔhú, yòushǒu déyì de shuō: \"Wǒ hái néng gěi shé tiānshang sì zhī jiǎo ne!\"", vi: "Một người vẽ xong con rắn rất nhanh, nhấc ấm rượu định uống, thấy người khác chưa vẽ xong, bèn tay trái cầm ấm rượu, tay phải đắc ý nói: \"Ta còn có thể vẽ thêm cho rắn bốn cái chân nữa kìa!\"" },
    { ...chars.wang, hanzi: "没等他把脚画完，另一个人已经画成了，一把夺过酒壶说：“蛇本来就没有脚，你怎么能给它添上脚呢？”说罢，仰起头把酒喝光了。", pinyin: "Méi děng tā bǎ jiǎo huàwán, lìng yí gè rén yǐjīng huàchéng le, yì bǎ duó guò jiǔhú shuō: \"Shé běnlái jiù méiyǒu jiǎo, nǐ zěnme néng gěi tā tiānshang jiǎo ne?\" Shuōbà, yǎng qǐ tóu bǎ jiǔ hēguāng le.", vi: "Chưa đợi anh ta vẽ xong chân, một người khác đã vẽ xong xuôi, giật lấy ấm rượu bảo: \"Rắn vốn dĩ không có chân, sao anh lại vẽ thêm chân cho nó?\" Nói đoạn, ngửa cổ uống cạn bầu rượu." },
    { ...chars.mary, sectionTitle: "课文二：成语寓意 (Ý nghĩa thành ngữ)", hanzi: "做多余的事情不仅无益，反而会把事情办糟，这就叫“画蛇添足，多此一举”。", pinyin: "Zuò duōyú de shìqing bùjǐn wúyì, fǎn'ér huì bǎ shìqing bàn zāo, zhè jiù jiào \"huà shé tiān zú, duō cǐ yì jǔ\".", vi: "Làm những việc thừa thãi không những vô ích, mà trái lại còn làm hỏng cả việc lớn, đó chính là \"Vẽ rắn thêm chân, thừa thãi vô ích\"." }
  ],

  // BÀI 56: 刻舟求剑
  "jc_3_1_56": [
    { ...chars.wang, sectionTitle: "课文一：江中落剑 (Rơi kiếm giữa dòng sông)", hanzi: "战国时期，楚国有一个人乘船渡江。船行至江心时，他不小心把佩带的宝剑掉进了滚滚江水之中。", pinyin: "Zhànguó shíqī, Chǔ guó yǒu yí gè rén chéng chuán dù jiāng. Chuán xíng zhì jiāngxīn shí, tā bù xiǎoxīn bǎ pèidài de bǎojiàn diàojìn le gǔngǔn jiāngshuǐ zhī zhōng.", vi: "Thời Chiến Quốc, có một người nước Sở đi thuyền qua sông. Khi thuyền ra đến giữa dòng, anh ta sơ ý đánh rơi thanh bảo kiếm đeo bên hông xuống dòng nước cuồn cuộn." },
    { ...chars.zhang, hanzi: "周围的人都惊呼起来，这个人却不慌不忙，拔出随身的小刀，在船舷上刻了一个记号，自言自语说：“我的宝剑就是从这里掉下去的。”", pinyin: "Zhōuwéi de rén dōu jīnghū qǐlai, zhè ge rén què bùhuāng-bùmáng, báchū suíshēn de xiǎodāo, zài chuánxián shàng kè le yí gè jìhao, zìyán-zìyǔ shuō: \"Wǒ de bǎojiàn jiù shì cóng zhèlǐ diàoxiàqu de.\"", vi: "Mọi người xung quanh đều kinh hãi kêu lên, người này lại ung dung không vội, rút chiếc dao găm nhỏ ra khắc một dấu trên mạn thuyền, lẩm bẩm: \"Bảo kiếm của ta chính là rơi xuống từ chỗ này.\"" },
    { ...chars.wang, hanzi: "等船靠岸停泊后，他便从船舷刻记号的地方跳入水中捞剑。船已经行走了很远，而剑沉在江底并不移动，像这样找剑岂不是太愚蠢了吗？", pinyin: "Děng chuán kào'àn tíngbó hòu, tā biàn cóng chuánxián kè jìhao de dìfang tiàorù shuǐ zhōng lāo jiàn. Chuán yǐjīng xíngzǒu le hěn yuǎn, ér jiàn chén zài jiāngdǐ bìng bù yídòng, xiàng zhèyàng zhǎo jiàn qǐbúshì tài yúchǔn le ma?", vi: "Đợi thuyền cập bến đỗ lại, anh ta bèn từ chỗ khắc dấu trên mạn thuyền nhảy xuống nước mò kiếm. Thuyền đã đi rất xa rồi, trong khi kiếm chìm dưới đáy sông đâu có di chuyển, tìm kiếm theo cách này há chẳng phải quá đỗi ngu muội sao?" },
    { ...chars.edward, sectionTitle: "课文二：认识论启示 (Bài học nhận thức luận)", hanzi: "客观事物是不断发展变化的，如果固守陈规、不知变通，必然会犯“刻舟求剑”的教条主义错误。", pinyin: "Kèguān shìwù shì búduàn fāzhǎn biànhuà de, rúguǒ gùshǒu-chéngguī, bùzhī biàntōng, bìrán huì fàn \"kè zhōu qiú jiàn\" de jiàotiáozhǔyì cuòwù.", vi: "Sự vật khách quan luôn không ngừng vận động biến đổi, nếu cố chấp rập khuôn, không biết linh hoạt thích ứng thì ắt sẽ phạm phải sai lầm giáo điều \"khắc thuyền tìm kiếm\"." }
  ],

  // BÀI 57: 滥竽充数
  "jc_3_1_57": [
    { ...chars.wang, sectionTitle: "课文一：齐宣王的乐队 (Dàn nhạc của Tề Tuyên Vương)", hanzi: "战国时，齐宣王喜欢听吹竽，而且每次都要三百人一起合奏。有个南郭先生根本不会吹竽，却设法混进了乐队，拿着俸禄享受优待。", pinyin: "Zhànguó shí, Qí Xuānwáng xǐhuan tīng chuī yú, érqiě měi cì dōu yào sānbǎi rén yìqǐ hézòu. Yǒu gè Nánguō xiānsheng gēnběn bú huì chuī yú, què shèfǎ hùnjìn le yuèduì, ná zhe fènglù xiǎngshòu yōudài.", vi: "Thời Chiến Quốc, Tề Tuyên Vương thích nghe thổi đàn vu, hơn nữa mỗi lần tấu nhạc đều bắt 300 người hợp xướng. Có Nam Quách tiên sinh căn bản không biết thổi vu, nhưng lại tìm cách trà trộn vào dàn nhạc, lĩnh lương bổng hưởng thụ bổng lộc." },
    { ...chars.zhang, hanzi: "每次合奏，南郭先生就装模作样地摇头晃脑，按着音孔，别人吹他也吹，瞒过了齐宣王好几年。", pinyin: "Měi cì hézòu, Nánguō xiānsheng jiù zhuāngmú-zuòyàng de yáotóu-huàngnǎo, àn zhe yīnkǒng, biérén chuī tā yě chuī, mánguò le Qí Xuānwáng hǎo jǐ nián.", vi: "Mỗi lần hòa tấu, Nam Quách tiên sinh làm bộ làm tịch lắc lư cái đầu, bấm ngón tay vào lỗ đàn, người ta thổi ông ta cũng vờ thổi, qua mặt được Tề Tuyên Vương suốt mấy năm trời." },
    { ...chars.wang, hanzi: "后来齐宣王死了，齐湣王继位，他喜欢听乐师一个个单独吹奏。南郭先生听到这个消息，吓得连夜收拾包袱悄悄溜走了。", pinyin: "Hòulái Qí Xuānwáng sǐ le, Qí Mǐnwáng jìwèi, tā xǐhuan tīng yuèshī yígè-yígè dāndú chuīzòu. Nánguō xiānsheng tīngdào zhè ge xiāoxi, xià de liányè shōushi bāofu qiāoqiāo liūzǒu le.", vi: "Về sau Tề Tuyên Vương qua đời, Tề Mẫn Vương lên ngôi, ông vua mới lại thích nghe từng nhạc công biểu diễn solo độc tấu. Nam Quách tiên sinh nghe ngóng được tin này, sợ hết hồn gói ghém hành lý trong đêm chuồn mất hút." },
    { ...chars.roland, sectionTitle: "课文二：才学真伪 (Chân tài thực học)", hanzi: "没有真才实学的人混在行家里充数，一旦面临严格考核，迟早会原形毕露。", pinyin: "Méiyǒu zhēncái-shíxué de rén hùn zài hángjiā lǐ chōngshù, yídàn miànlín yángé kǎohé, chízǎo huì yuánxíng-bìlù.", vi: "Kẻ không có chân tài thực học mà trà trộn vào hàng ngũ chuyên gia giả danh, một khi đối mặt khảo hạch nghiêm khắc thì sớm muộn cũng lộ nguyên hình." }
  ],

  // BÀI 58: 买椟还珠
  "jc_3_1_58": [
    { ...chars.wang, sectionTitle: "课文一：华丽的木匣与珍珠 (Chiếc tráp lộng lẫy & Viên ngọc quý)", hanzi: "楚国有个人有一颗硕大名贵的珍珠，想把它卖个好价钱，便用名贵的木材做了一个极其精致的木匣子，用香料熏得喷香。", pinyin: "Chǔ guó yǒu gè rén yǒu yì kē shuòdà míngguì de zhēnzhū, xiǎng bǎ tā mài gè hǎo jiàqián, biàn yòng míngguì de mùcái zuò le yí gè jíqí jīngzhì de mù xiázi, yòng xiāngliào xūn de pènhxiāng.", vi: "Nước Sở có người sở hữu một viên trân châu to lớn quý giá, muốn bán được giá cao, bèn dùng loại gỗ quý chế tác chiếc tráp cực kỳ tinh xảo, dùng hương liệu xông thơm nức mũi." },
    { ...chars.tian, hanzi: "他又用金线和翠鸟的羽毛在盒子上镶嵌出华丽的花纹。有个郑国人出高价买下了这个华丽的匣子，却把珍贵的珍珠退还给了楚人。", pinyin: "Tā yòu yòng jīnxiàn hé cuìniǎo de yǔmáo zài hézi shàng xiāngqiàn chū huálì de huāwén. Yǒu gè Zhèng guó rén chū gāojià mǎixià le zhè ge huálì de xiázi, què bǎ zhēnguì de zhēnzhū tuìhuán gěi le Chǔ rén.", vi: "Anh ta còn dùng chỉ vàng và lông chim phỉ thúy khảm nạm lên tráp những đường hoa văn lộng lẫy. Có một người nước Trịnh trả giá cao mua chiếc tráp hoa lệ đó, nhưng lại trả lại viên ngọc quý giá cho người nước Sở." },
    { ...chars.wang, hanzi: "这个楚人可以说是善于卖匣子，却绝不善于卖珍珠啊！", pinyin: "Zhè ge Chǔ rén kěyǐ shuō shì shànyú mài xiázi, què juébú shànyú mài zhēnzhū a!", vi: "Người nước Sở này có thể coi là khéo bán hộp tráp, nhưng tuyệt nhiên chẳng biết bán ngọc trân châu chút nào!" },
    { ...chars.david, sectionTitle: "课文二：主次颠倒的反思 (Bài học đảo lộn gốc ngọn)", hanzi: "这则成语生动批判了那些取舍不当、舍本逐末，只看华丽外表而忽略内在核心价值的人。", pinyin: "Zhè zé chéngyǔ shēngdòng pīpàn le nàxiē qǔshě-bùdàng, shěběn-zhúmò, zhǐ kàn huálì wàibiǎo ér hūlüè nèizài héxīn jiàzhí de rén.", vi: "Thành ngữ này phê phán sinh động những ai chọn lựa bất cập, bỏ gốc lấy ngọn, chỉ chăm chăm vẻ hào nhoáng bề ngoài mà xem nhẹ giá trị cốt lõi bên trong." }
  ],

  // BÀI 59: 自相矛盾
  "jc_3_1_59": [
    { ...chars.wang, sectionTitle: "课文一：最坚固的盾与最锋利的矛 (Chiếc khiên vững nhất & Ngọn giáo sắc nhất)", hanzi: "楚国有个人在集市上卖矛和盾。他先举起自己的盾夸耀说：“我的盾坚固无比，世界上任何锋利的东西都刺不破它！”", pinyin: "Chǔ guó yǒu gè rén zài jíshì shàng mài máo hé dùn. Tā xiān jǔqǐ zìjǐ de dùn kuāyào shuō: \"Wǒ de dùn jiāngù-wúbǐ, shìjiè shàng rènhé fēnglì de dōngxi dōu cì bú pò tā!\"", vi: "Nước Sở có người bán mâu và khiên ở chợ. Anh ta giơ chiếc khiên lên khoe khoang: \"Khiên của ta cứng chắc vô địch, bất cứ thứ gì sắc nhọn trên đời cũng không tài nào đâm thủng được nó!\"" },
    { ...chars.zhang, hanzi: "紧接着他又举起自己的矛得意地夸口：“我的矛锋利绝伦，世界上任何坚固的东西都能轻易刺穿！”", pinyin: "Jǐnjiēzhe tā yòu jǔqǐ zìjǐ de máo déyì de kuākǒu: \"Wǒ de máo fēnglì-juélún, shìjiè shàng rènhé jiāngù de dōngxi dōu néng qīngyì cìchuān!\"", vi: "Ngay sau đó anh ta lại giơ ngọn mâu lên đắc ý huênh hoang: \"Mâu của ta sắc bén tột cùng, bất kể vật gì rắn chắc trên đời đều bị nó dễ dàng đâm thủng!\"" },
    { ...chars.tian, hanzi: "围观的人群中有人笑着问他：“如果用你的矛去刺你的盾，结果会怎么样呢？”那个楚人张口结舌，一句话也回答不上来。", pinyin: "Wéiguān de rénqún zhōng yǒurén xiào zhe wèn tā: \"Rúguǒ yòng nǐ de máo qù cì nǐ de dùn, jiéguǒ huì zěnmeyàng ne?\" Nà ge Chǔ rén zhāngkǒu-jiéshé, yí jù huà yě huídá bú shànglai.", vi: "Trong đám đông đứng xem có người cười hỏi: \"Nếu dùng chính ngọn mâu của anh đâm vào chiếc khiên của anh, thì kết quả sẽ thế nào?\" Người nước Sở nọ há hốc mồm cứng họng, không thốt nổi nửa lời." },
    { ...chars.edward, sectionTitle: "课文二：逻辑自洽的重要性 (Tầm quan trọng của tính logic)", hanzi: "说话办事不能前后抵触，否则就会陷入自相矛盾的逻辑困境。", pinyin: "Shuōhuà bànshì bù néng qiánhòu dǐchù, fǒuzé jiù huì xiànrù zì-xiāng-máodùn de luóji kùnjìng.", vi: "Lời nói việc làm không được trước sau chọi nhau, nếu không sẽ rơi vào nghịch cảnh logic \"tự mình mâu thuẫn\"." }
  ],

  // BÀI 60: 拔苗助长
  "jc_3_1_60": [
    { ...chars.wang, sectionTitle: "课文一：急躁拔苗 (Nôn nóng nhổ mạ)", hanzi: "宋国有个农夫嫌田里的禾苗长得太慢，天天盼着禾苗快点儿长大。他整天在田边转来转去，苦思冥想有什么妙法。", pinyin: "Sòng guó yǒu gè nóngfū xián tián lǐ de hémiáo zhǎng de tài màn, tiāntiān pàn zhe hémiáo kuài diǎnr zhǎngdà. Tā zhěng tiān zài tiánbiān zhuàn lái zhuàn qù, kǔsī-míngxiǎng yǒu shénme miàofǎ.", vi: "Nước Tống có bác nông dân chê mạ non trên đồng lớn quá chậm, ngày nào cũng mong mạ lớn vùn vụt. Bác ta đi đi lại lại bên bờ ruộng cả ngày, vắt óc suy nghĩ xem có diệu kế gì chăng." },
    { ...chars.zhang, hanzi: "终于有一天，他想出了一个主意，跑到田里把禾苗一棵一棵地往上拔高了一截。他从早晨一直拔到太阳落山，累得筋疲力尽。", pinyin: "Zhōngyú yǒu yì tiān, tā xiǎngchū le yí gè zhǔyi, pǎo dào tián lǐ bǎ hémiáo yì kē yì kē de wǎng shàng bágāo le yì jié. Tā cóng zǎochen yìzhí bá dào tàiyáng luòshān, lèi de jīnpí-lìjìn.", vi: "Cuối cùng có một hôm, bác ta nghĩ ra một kế, chạy ra đồng nhổ từng gốc mạ kéo nhích cao lên một đoạn. Bác ta nhổ từ sáng sớm tới tận lúc mặt trời lặn, mệt bã người đứt hơi." },
    { ...chars.wang, hanzi: "回到家里，他气喘吁吁地对家人说：“今天可把我累坏了，我帮禾苗长高了好几寸！”他的儿子急忙跑到田里一看，禾苗全都枯死了。", pinyin: "Huí dào jiā lǐ, tā qìchuǎn-xūxū de duì jiārén shuō: \"Jīntiān kě bǎ wǒ lèi huài le, wǒ bāng hémiáo zhǎng gāo le hǎojǐ cùn!\" Tā de érzi jímáng pǎo dào tián lǐ yí kàn, hémiáo quándōu kūsǐ le.", vi: "Về tới nhà, bác ta thở hổn hển bảo người nhà: \"Hôm nay mệt đứt hơi, nhưng ta đã giúp mạ trên đồng cao thêm mấy tấc!\" Con trai vội vàng chạy ra đồng xem, thì hỡi ôi mạ non đều héo rũ chết khô hết." },
    { ...chars.mary, sectionTitle: "课文二：尊重客观规律 (Tôn trọng quy luật khách quan)", hanzi: "事物的发展都有其内在客观规律，急于求成、违反规律盲动，只会适得其反，这就是“拔苗助长”的沉痛教训。", pinyin: "Shìwù de fāzhǎn dōu yǒu qí nèizài kèguān guīlǜ, jíyú-qiúchéng, wéifǎn guīlǜ mángdòng, zhǐ huì shìdéqífǎn, zhè jiù shì \"bá miáo zhù zhǎng\" de chéntòng jiàoxun.", vi: "Sự phát triển của vạn vật đều có quy luật khách quan bên trong, nôn nóng muốn thành công ngay, hành động mù quáng trái quy luật thì chỉ chuốc lấy kết quả ngược lại, đó là bài học đắt giá của \"Nhổ mạ giúp lớn\"." }
  ],

  // BÀI 61: 井底之蛙
  "jc_3_1_61": [
    { ...chars.wang, sectionTitle: "课文一：枯井里的青蛙 (Chú ếch trong đáy giếng cạn)", hanzi: "一口废井里住着一只青蛙。它对从东海来的大鳖夸耀说：“你看我住在这里多么快乐！高兴了就在井栏跳跃，疲倦了就在洞壁歇息，井里的水虫都不如我自在！”", pinyin: "Yì kǒu fèijǐng lǐ zhù zhe yì zhī qīngwā. Tā duì cóng dōnghǎi lái de dà biē kuāyào shuō: \"Nǐ kàn wǒ zhù zài zhèlǐ duōme kuàilè! Gāoxìng le jiù zài jǐnglán tiàoyuè, píjuàn le jiù zài dòngbì xiēxi, jǐng lǐ de shuǐchóng dōu bùrú wǒ zìzài!\"", vi: "Trong một miệng giếng cạn có một chú ếch sinh sống. Nó khoe với con rùa lớn từ Biển Đông đến: \"Bác xem tôi sống ở đây sướng biết bao! Vui thì nhảy nhót quanh thành giếng, mệt thì nép vào vách hang nghỉ ngơi, tôm cá bọ nước trong giếng chẳng ai tự tại bằng tôi!\"" },
    { ...chars.tian, hanzi: "东海大鳖便向它描绘大海：“千里之远，不足以形容大海的辽阔；千仞之高，不足以穷尽大海的深邃。大禹时期十年九涝，海水不涨；商汤时期八年七旱，海水不落。”", pinyin: "Dōnghǎi dà biē biàn xiàng tā miáohuì dàhǎi: \"Qiānlǐ zhī yuǎn, bùzú yǐ xíngróng dàhǎi de liáokuò; qiānrèn zhī gāo, bùzú yǐ qióngjìn dàhǎi de shēnsuì. Dàyǔ shíqī shí nián jiǔ lào, hǎishuǐ bù zhǎng; Shāngtāng shíqī bā nián qī hàn, hǎishuǐ bú luò.\"", vi: "Rùa Biển Đông bèn miêu tả biển cả cho ếch nghe: \"Nghìn dặm đường dài chưa đủ ví hết độ bao la của biển; ngàn trượng núi cao chưa đủ đo hết độ thâm sâu khôn cùng. Thời vua Đại Vũ mười năm chín lụt, nước biển không dâng; thời vua Thang tám năm bảy hạn, biển cả chẳng vơi.\"" },
    { ...chars.wang, hanzi: "井底的青蛙听了大鳖的话，瞠目结舌，顿时觉得自己渺小极了。", pinyin: "Jǐngdǐ de qīngwā tīng le dà biē de huà, chēngmù-jiéshé, dùnshí juéde zìjǐ miǎoxiǎo jí le.", vi: "Chú ếch đáy giếng nghe xong lời rùa biển, ngơ ngác trố mắt, bỗng thấy bản thân mình nhỏ bé khôn cùng." },
    { ...chars.mike, sectionTitle: "课文二：开阔眼界格局 (Mở rộng tầm mắt & khí phách)", hanzi: "“井底之蛙”告诫我们千万不能固步自封、自高自大，必须登高望远，保持对未知世界的敬畏与探索之心。", pinyin: "\"Jǐng dǐ zhī wā\" gàojiè wǒmen qiānwàn bù néng gùbù-zìfēng, zìgāo-zìdà, bìxū dēnggāo-wàngyuǎn, bǎochí duì wèizhī shìjiè de jìngwèi yǔ tànsuǒ zhī xīn.", vi: "\"Ếch ngồi đáy giếng\" nhắc nhở chúng ta tuyệt đối không được tự trói mình, tự cao tự đại, phải đứng trên đỉnh cao nhìn ra xa, giữ trọn lòng kính ngưỡng và tinh thần khám phá thế giới bao la." }
  ],

  // BÀI 62: 孟母三迁
  "jc_3_1_62": [
    { ...chars.wang, sectionTitle: "课文一：孟母择邻而居 (Mẹ Mạnh Tử chọn bạn chọn láng giềng)", hanzi: "古代大思想家孟子幼年丧父，母亲仉氏对他寄予厚望。最初他们家住在墓地附近，年幼的孟子就常和小伙伴玩筑墓、哭丧的游戏。", pinyin: "Gǔdài dà sīxiǎngjiā Mèngzǐ yòunián sàng fù, mǔqīn Zhǎng shì duì tā jìyǔ hòuwàng. Zuìchū tāmen jiā zhù zài mùdì fùjìn, niányòu de Mèngzǐ jiù cháng hé xiǎohuǒbàn wán zhùmù, kūsāng de yóuxì.", vi: "Đại tư tưởng gia Mạnh Tử mồ côi cha từ thuở nhỏ, mẹ là bà Chưởng thị đặt nhiều kỳ vọng vào con. Ban đầu nhà ở gần nghĩa địa, Mạnh Tử thơ ấu thường cùng bạn nhỏ chơi trò đắp mộ, khóc tang." },
    { ...chars.tian, hanzi: "孟母皱起眉头说：“这里不是适合养育孩子的地方。”于是她把家搬到了集市旁边。孟子又跟着商人学起了杀猪、讨价还价的买卖营生。", pinyin: "Mèng mǔ zhòuqǐ méitóu shuō: \"Zhèlǐ bú shì shìhé yǎngyù háizi de dìfang.\" Yúshì tā bǎ jiā bān dào le jíshì pángbiān. Mèngzǐ yòu gēnzhe shāngrén xué qǐ le shā zhū, tǎojià-huánjià de mǎimai yíngshēng.", vi: "Mẹ Mạnh Tử cau mày nói: \"Nơi đây không phải chốn nuôi dạy con cái.\" Bèn dời nhà đến cạnh khu chợ buôn bán. Mạnh Tử lại bắt chước dân buôn học mổ lợn, ngã giá mặc cả chuyện làm ăn." },
    { ...chars.wang, hanzi: "孟母再次叹息搬家，这次把家搬到了学宫学堂旁边。从此孟子每天看到的是读书人的彬彬有礼、诵读经书，他也跟着进退作揖、勤奋好学。孟母欣慰地说：“这里才真正是可以安家教子的地方啊！”", pinyin: "Mèng mǔ zàicì tànxī bānjiā, zhè cì bǎ jiā bān dào le xuégōng xuétáng pángbiān. Cóngcǐ Mèngzǐ měi tiān kàndào de shì dúshūrén de bīnbīn-yǒulǐ, sòngdú jīngshū, tā yě gēnzhe jìntuì-zuòyī, qínfèn hàoxué. Mèng mǔ xīnwèi de shuō: \"Zhèlǐ cái zhēnzhèng shì kěyǐ ānjiā jiàozǐ de dìfang a!\"", vi: "Mẹ Mạnh Tử lại thở dài chuyển nhà, lần này chuyển đến cạnh trường học. Từ đó Mạnh Tử ngày ngày nhìn thấy các sĩ tử văn phong lễ phép, đọc tụng kinh thư, bèn bắt chước theo phép tắc lễ nghĩa, chăm chỉ ham học. Mẹ Mạnh Tử mừng rỡ nói: \"Đây mới thực sự là nơi định cư dạy con!\"" },
    { ...chars.edward, sectionTitle: "课文二：环境育人的力量 (Sức mạnh hoàn cảnh giáo dục)", hanzi: "“孟母三迁”彰显了良好环境对人性格塑造与道德成长的巨大影响，至今仍是中国家庭教育的崇高典范。", pinyin: "\"Mèng mǔ sān qiān\" zhāngxiǎn le liánghǎo huánjìng duì rén xìnggé shùzào yǔ dàodé chéngzhǎng de jùdà yǐngxiǎng, zhìjīn réng shì Zhōngguó jiātíng jiàoyù de chónggāo diǎnfàn.", vi: "\"Mẹ Mạnh Tử ba lần chuyển nhà\" nêu bật ảnh hưởng to lớn của môi trường sống tới sự uốn nắn nhân cách và đạo đức của một con người, đến nay vẫn là chuẩn mực sáng ngời của giáo dục gia đình Trung Hoa." }
  ],

  // BÀI 63: 闻鸡起舞
  "jc_3_1_63": [
    { ...chars.wang, sectionTitle: "课文一：祖逖与刘琨的壮志 (Chí khí của Tổ Địch và Lưu Côn)", hanzi: "晋代青年名将祖逖与好友刘琨同住一室。他们胸怀报国大志，深感国家动荡、外族侵扰，决心练就一身过硬的文韬武略来收复失地。", pinyin: "Jìn dài qīngnián míngjiàng Zǔ Tì yǔ hǎoyǒu Liú Kūn tóng zhù yí shì. Tāmen xiōnghuái bàoguó dàzhì, shēngǎn guójiā dòngdàng, wàizú qīnrǎo, juéxīn liànjiù yì shēn guòyìng de wéntāo-wǔlüè lái shōufù shīdì.", vi: "Thời nhà Tấn, viên danh tướng trẻ tuổi Tổ Địch và bạn thân Lưu Côn ở chung một phòng. Họ nuôi chí lớn báo đền nợ nước, đau lòng trước cảnh quốc gia tao loạn, giặc ngoại xâm quấy nhiễu, quyết tâm rèn luyện văn võ song toàn để thu hồi bờ cõi non sông." },
    { ...chars.zhang, hanzi: "半夜听到荒鸡报晓，祖逖一脚踢醒刘琨说：“听，这并不是不祥之兆，而是催促我们起身的战鼓！”", pinyin: "Bànyè tīngdào huāngjī bàoxiǎo, Zǔ Tì yì jiǎo tī xǐng Liú Kūn shuō: \"Tīng, zhè bìng bú shì bùxiáng zhī zhào, ér shì cuīcù wǒmen qǐshēn de zhàngǔ!\"", vi: "Nửa đêm nghe tiếng gà gáy sớm, Tổ Địch đá lay Lưu Côn dậy bảo: \"Lắng nghe xem, đây đâu phải điềm gở, mà chính là tiếng trống trận giục giã chúng ta thức dậy!\"" },
    { ...chars.wang, hanzi: "两人立即翻身起床，拔出长剑在星空下挥汗练习，寒来暑往，从不间断。后来祖逖率部北伐中流击楫，收复了黄河以南大片大好河山！", pinyin: "Liǎng rén lìjí fānshēn qǐchuáng, báchū chángjiàn zài xīngkōng xià huīhàn liànxí, hánlái-shǔwǎng, cóng bù jiànduàn. Hòulái Zǔ Tì shuàibù běifá zhōngliú-jījī, shōufù le Huánghé yǐnán dàpiàn dàhǎo héshān!", vi: "Hai người lập tức vùng dậy, rút trường kiếm múa luyện miệt mài dưới vòm trời sao, đông qua hè tới chưa từng ngơi nghỉ. Về sau Tổ Địch thống lĩnh đại quân bắc phạt, đập mái chèo giữa dòng thề quét sạch quân thù, thu phục lại giang sơn gấm vóc phía nam Hoàng Hà!" },
    { ...chars.mike, sectionTitle: "课文二：发奋图强的精神 (Tinh thần phát phấn vươn lên)", hanzi: "“闻鸡起舞”激励着一代又一代有志青年把握光阴，在黎明破晓之际发奋自强，勇挑历史重担！", pinyin: "\"Wén jī qǐ wǔ\" jīlì zhe yí dài yòu yí dài yǒuzhì qīngnián bǎwò guāngyīn, zài límíng pòxiǎo zhī jì fāfèn-zìqiáng, yǒng tiāo lìshǐ zhòngdàn!", vi: "\"Nghe gà gáy dậy múa kiếm\" khích lệ biết bao thế hệ thanh niên ôm ấp hoài bão trân quý từng tấc thời gian, ngay từ buổi bình minh đã phát phấn tự cường, gánh vác sứ mệnh giang sơn!" }
  ],

  // BÀI 64: 中国茶文化与茶道哲学
  "jc_3_2_64": [
    { ...chars.tea_master, sectionTitle: "课文一：茶艺演示与品茗 (Nghệ thuật thưởng trà)", hanzi: "各位贵宾请看，这是产自杭州西湖的明前龙井。品茶讲究‘一闻香、二观色、三品味’。请各位先嗅这盖碗中的清芬。", pinyin: "Gèwèi guìbīn qǐng kàn, zhè shì chǎnzì Hángzhōu Xīhú de míngqián Lóngjǐng. Pǐn chá jiǎngjiu 'yī wén xiāng, èr guān sè, sān pǐn wèi'. Qǐng gèwèi xiān xiù zhè gàiwǎn zhōng de qīngfēn.", vi: "Kính mời quý khách chiêm ngưỡng, đây là trà Long Tỉnh hái trước tiết Thanh Minh tại Tây Hồ Hàng Châu. Thưởng trà quý ở 'nhất ngửi hương, nhị ngắm sắc, tam nếm vị'. Xin mời quý vị đón lấy chén sứ để cảm nhận hương thanh khiết." },
    { ...chars.roland, hanzi: "香气清幽淡雅，茶汤碧绿澄澈，入口微苦却有极其甘醇绵长的回甘，令人神清气爽！", pinyin: "Xiāngqì qīngyōu dànyǎ, chátāng bìlǜ chéngchè, rùkǒu wēikǔ què yǒu jíqí gānchún miáncháng de huígān, lìng rén shénqīng-qìshuǎng!", vi: "Hương thơm thanh tao u nhã, nước trà xanh biếc trong vắt, nhấp ngụm đầu hơi đắng nhưng hậu vị ngọt đậm đà kéo dài, khoan khoái cả tâm hồn!" },
    { ...chars.wang, sectionTitle: "课文二：茶道精神的核心 (Cốt lõi tinh thần Trà đạo)", hanzi: "中国茶道以‘廉、美、和、敬’为四德。唐代茶圣陆羽著《茶经》，将饮茶提升为涤荡心灵、体悟天人合一境界的修身之道。", pinyin: "Zhōngguó chádào yǐ 'lián, měi, hé, jìng' wéi sì dé. Táng dài Chásèng Lù Yǔ zhù \"Chá Jīng\", jiāng yǐnchá tíshēng wéi dídàng xīnlíng, tǐwù tiānrén-héyī jìngjiè de xiūshēn zhī dào.", vi: "Trà đạo Trung Hoa lấy 'Liêm, Mỹ, Hòa, Kính' làm bốn đức tính cốt lõi. Thánh trà Lục Vũ thời Đường viết bộ \"Trà Kinh\", đã nâng việc uống trà thành con đường tu thân gột rửa tâm hồn, lĩnh ngộ cảnh giới Thiên nhân hợp nhất." },
    { ...chars.mike, hanzi: "茶如人生，苦尽甘来；在喧嚣的现代都市中泡一壶茶，能让人找回内心的宁静与从容。", pinyin: "Chá rú rénshēng, kǔjìn-gānlái; zài xuānxiāo de xiàndài dūshì zhōng pào yì hú chá, néng ràng rén zhǎohuí nèixīn de níngjìng yǔ cóngróng.", vi: "Trà tựa như một đời người, khổ tận cam lai; giữa phố thị hiện đại ồn ào được pha một ấm trà tĩnh tại, quả là giúp con người tìm lại sự an yên và thanh thản trong tâm hồn." }
  ],

  // BÀI 65: 中国传统节日：春节与中秋
  "jc_3_2_65": [
    { ...chars.tian, sectionTitle: "课文一：千门万户曈曈日 (Xuân Tiết: Đoàn viên & Khởi sắc)", hanzi: "在我们中国人心中，春节是一年中最重要的日子。无论离家多远，大家都要赶在除夕夜回到父母身边吃团圆年夜饭、守岁包饺子。", pinyin: "Zài wǒmen Zhōngguó rén xīn zhōng, Chūnjié shì yì nián zhōng zuì zhòngyào de rìzi. Wúlùn lí jiā duō yuǎn, dàjiā dōu yào gǎn zài chúxī yè huí dào fùmǔ shēnbiān chī tuányuán niányèfàn, shǒusuì bāo jiǎozi.", vi: "Trong tâm khảm của người Trung Quốc chúng mình, Tết Nguyên Đán là dịp quan trọng nhất trong năm. Dù đi xa muôn dặm, ai nấy đều kịp về bên cha mẹ trong đêm Giao thừa ăn bữa cơm tất niên đoàn viên, đón giao thừa và gói bánh sủi cảo." },
    { ...chars.zhang, hanzi: "贴春联、挂红灯、放爆竹，还要给长辈拜年道贺，孩子们最开心的就是拿到压岁钱，处处洋溢着祥和喜庆。", pinyin: "Tiē chūnlián, guà hóngdēng, fàng bàozhú, hái yào gěi zhǎngbèi bàinián dàohè, háizimen zuì kāixīn de jiù shì nádào yāsuìqián, chùchù yángyì zhe xiánghé xǐqìng.", vi: "Dán câu đối đỏ, treo đèn lồng, đốt pháo hoa, lại còn chúc thọ bề trên, lũ trẻ háo hức nhất là được nhận bao lì xì đỏ, khắp nơi tràn ngập không khí cát tường hân hoan." },
    { ...chars.wang, sectionTitle: "课文二：但愿人长久 (Trung Thu: Ngắm trăng & Nhớ cố hương)", hanzi: "而八月十五中秋节，则是寄托思乡之情的诗意节日。人们品尝香甜的月饼，仰望如玉盘般的皎洁明月，吟诵‘但愿人长久，千里共婵娟’。", pinyin: "Ér bā yuè shíwǔ Zhōngqiūjié, zé shì jìtuō sīxiāng zhī qíng de shīyì jiérì. Rénmen pǐncháng xiāngtián de yuèbǐng, yǎngwàng rú yùpán bān de jiǎojié míngyuè, yínsòng 'dànyuàn rén chángjiǔ, qiānlǐ gòng chánjuān'.", vi: "Còn Tết Trung Thu rằm tháng Tám lại là ngày lễ thi vị gửi gắm nỗi nhớ quê hương sâu lắng. Mọi người cùng nhâm nhi bánh trung thu thơm ngọt, ngắm vầng trăng rằm vằng vặc tựa đĩa ngọc, ngân nga câu thơ 'Nguyện chúc muôn người bình an mãi, ngàn dặm cùng soi bóng trăng thanh'." },
    { ...chars.mary, hanzi: "这两个节日虽然风俗不同，但核心都是‘家与团圆’，展现了中华民族深厚的人伦亲情与文化向心力。", pinyin: "Zhè liǎng gè jiérì suīrán fēngsú bùtóng, dàn héxīn dōu shì 'jiā yǔ tuányuán', zhǎnxiàn le Zhōnghuá mínzú shēnhòu de rénlún qīnqíng yǔ wénhuà xiàngxīnlì.", vi: "Hai ngày lễ này tuy phong tục tập quán khác nhau, nhưng cốt lõi đều hội tụ ở chữ 'Gia đình và Đoàn viên', thể hiện tình thân luân lý sâu nặng và sức mạnh hướng tâm văn hóa của dân tộc Trung Hoa." }
  ],

  // BÀI 66: 中医养生与阴阳平衡
  "jc_3_2_66": [
    { ...chars.li, sectionTitle: "课文一：天人相应的医学宝库 (Kho tàng y học Thiên nhân tương ứng)", hanzi: "中医有着几千年的悠久历史，《黄帝内经》奠定了中医的理论基础。中医认为人体是一个有机的整体，人与自然环境息息相关。", pinyin: "Zhōngyī yǒu zhe jǐ qiān nián de yōujiǔ lìshǐ, \"Huángdì Nèijīng\" diàndìng le Zhōngyī de lǐlùn jīchǔ. Zhōngyī rènwéi réntǐ shì yí gè yǒujī de zhěngtǐ, rén yǔ zìrán huánjìng xīxī-xiāngguān.", vi: "Đông y sở hữu lịch sử mấy ngàn năm hào hùng, bộ kinh điển \"Hoàng Đế Nội Kinh\" đã đặt nền móng lý luận vững chắc cho Trung y. Đông y quan niệm cơ thể con người là một chỉnh thể hữu cơ, con người gắn bó khăng khít với môi trường tự nhiên." },
    { ...chars.edward, hanzi: "我听说中医治病最讲究‘阴阳平衡’和‘望闻问切’四诊法，这与西方现代医学有什么区别？", pinyin: "Wǒ tīngshuō Zhōngyī zhìbìng zuì jiǎngjiu 'yīnyáng pínghéng' hé 'wàng wén wèn qiè' sì zhěnfǎ, zhè yǔ xīfāng xiàndài yīxué yǒu shénme qūbié?", vi: "Em nghe nói chữa bệnh theo Đông y coi trọng nhất 'Cân bằng âm dương' và tứ chẩn 'Vọng, Văn, Vấn, Thiết', điều này khác biệt thế nào với tây y hiện đại?" },
    { ...chars.li, hanzi: "西医注重微观靶向杀菌消炎，而中医强调宏观辨证施治，通过草药调理气血、针灸疏通经络，达到‘阴平阳秘，精神乃治’的治未病境界。", pinyin: "Xīyī zhùzhòng wēiguān bǎxiàng shājūn xiāoyán, ér Zhōngyī qiángdiào hóngguān biànzhèng-shīzhì, tōngguò cǎoyào tiáolǐ qìxuè, zhēnjiǔ shūtōng jīngluò, dádào 'yīn píng yáng mì, jīngshén nǎi zhì' de zhì-wèibìng jìngjiè.", vi: "Tây y chú trọng đích ngắm vi mô diệt khuẩn kháng viêm, còn Đông y nhấn mạnh biện chứng luận trị ở tầm vĩ mô, thông qua thảo dược bồi bổ khí huyết, châm cứu đã thông kinh lạc, đạt đến cảnh giới 'Âm bình dương vững, tinh thần an định', phòng bệnh từ lúc chưa phát tác." },
    { ...chars.mary, hanzi: "这种崇尚自然、标本兼治的东方医学智慧，正在受到全球医学界越来越高度的重视！", pinyin: "Zhè zhǒng chóngshàng zìrán, biāoběn-jiānzhì de dōngfāng yīxué zhìhuì, zhèngzài shòudào quánqiú yīxuéjiè yuè lái yuè gāodù de zhòngshì!", vi: "Trí tuệ y học phương Đông chuộng sự hài hòa tự nhiên, chữa trị đồng thời cả gốc lẫn ngọn này đang nhận được sự tôn vinh ngày càng cao của giới y khoa toàn cầu!" }
  ],

  // BÀI 67: 中国的书法艺术与汉字之美
  "jc_3_2_67": [
    { ...chars.wang, sectionTitle: "课文一：无言之诗与无图之画 (Thơ không lời & Họa không hình)", hanzi: "中国书法被誉为‘无言之诗，无行之舞，无图之画，无声之乐’。汉字从甲骨文、金文、篆书、隶书，演变为楷书、行书和草书。", pinyin: "Zhōngguó shūfǎ bèi yù wéi 'wúyán zhī shī, wùxíng zhī wǔ, wútú zhī huà, wúshēng zhī yuè'. Hànzì cóng jiǎgǔwén, jīnwén, zhuànshū, lìshū, yǎnbiàn wéi kǎishū, xíngshū hé cǎoshū.", vi: "Thư pháp Trung Hoa được xưng tụng là 'bài thơ không lời, điệu múa vô hình, bức tranh không màu, bản nhạc không tiếng'. Chữ Hán từ giáp cốt văn, kim văn, triện thư, lệ thư, dần diễn biến thành khải thư, hành thư và thảo thư." },
    { ...chars.roland, hanzi: "我临摹王羲之的《兰亭集序》，其行云流水、刚柔并济的笔触真是绝妙非凡！", pinyin: "Wǒ línmó Wáng Xīzhī de \"Lántíng Jí Xù\", qí xíngyún-liúshuǐ, gāngróu-bìngjì de bǐchù zhēn shì juémiào fēifán!", vi: "Em tập đồ theo tác phẩm \"Lan Đình Tập Tự\" của Vương Hy Chi, những nét bút tựa mây trôi nước chảy, cương nhu hòa quyện quả thực tuyệt mỹ khôn cùng!" },
    { ...chars.wang, hanzi: "书法讲究‘执笔在心，运笔在气’。文房四宝笔、墨、纸、砚相濡以沫，落笔轻重缓急之间，宣泄出书法家的胸襟气度与生命情怀。", pinyin: "Shūfǎ jiǎngjiu 'zhíbǐ zài xīn, yùnbǐ zài qì'. Wénfáng sìbǎo bǐ, mò, zhǐ, yàn xiāngrúyǐmò, luòbǐ qīng-zhòng-huǎn-jí zhījiān, xuānxiè chū shūfǎjiā de xiōngjīn qìdù yǔ shēngmìng qínghuái.", vi: "Thư pháp đề cao nguyên lý 'cầm bút tại tâm, vận bút tại khí'. Văn phòng tứ bảo gồm bút, mực, giấy, nghiên gắn bó khăng khít, giữa những nét hạ bút nặng nhẹ chậm nhanh đã bộc lộ trọn vẹn khí phách tâm can và tình cảm nhân sinh của người nghệ sĩ." }
  ],

  // BÀI 68: 人际关系中的“面子”与“人情”
  "jc_3_2_68": [
    { ...chars.david, sectionTitle: "课文一：深入理解中国社会心理 (Thấu hiểu tâm lý xã hội Trung Quốc)", hanzi: "王老师，在与中国朋友交往中，我常常听到大家谈起‘面子’和‘人情’，这背后蕴藏着怎样的文化心理？", pinyin: "Wáng lǎoshī, zài yǔ Zhōngguó péngyou jiāowǎng zhōng, wǒ chángcháng tīngdào dàjiā tánqǐ 'miànzi' hé 'rénqíng', zhè bèihòu yùncáng zhe zěnyàng de wénhuà xīnlǐ?", vi: "Thưa thầy Vương, trong giao tiếp với bạn bè Trung Quốc, em thường nghe mọi người nhắc tới 'thể diện' và 'nhân tình', ẩn sau điều này là tâm lý văn hóa như thế nào ạ?" },
    { ...chars.wang, hanzi: "‘面子’代表着个人的尊严、社会声誉与被尊重的程度。在人际交往中，‘给面子’意味着尊重对方，避免让别人‘丢面子’、陷入难堪。", pinyin: "'Miànzi' dàibiǎo zhe gèrén de zūnyán, shèhuì shēngyù yǔ bèi zūnzhòng de chéngdù. Zài rénjì jiāowǎng zhōng, 'gěi miànzi' yìwèizhe zūnzhòng duìfāng, bìmiǎn ràng biérén 'diū miànzi', xiànrù nánkān.", vi: "'Thể diện' đại diện cho nhân phẩm, uy tín xã hội và mức độ được tôn trọng của một cá nhân. Trong giao tiếp, 'cho thể diện' nghĩa là tôn trọng đối phương, tránh để người khác 'mất mặt' rơi vào thế khó xử." },
    { ...chars.zhang, hanzi: "而‘人情’则体现了礼尚往来与互助互惠的情感纽带。古人讲‘投我以桃，报之以李’，在他人需要时施以援手，维系着社会的和谐与温情。", pinyin: "Ér 'rénqíng' zé tǐxiàn le lǐshàng-wǎnglái yǔ hùzhù-hùhuì de qínggǎn niǔdài. Gǔrén jiǎng 'tóu wǒ yǐ táo, bào zhī yǐ lǐ', zài tārén xūyào shí shī yǐ yuánshǒu, wéixì zhe shèhuì de héxié yǔ wēnqíng.", vi: "Còn 'nhân tình' lại thể hiện mối dây tình cảm qua lại có qua có lại và tương trợ lẫn nhau. Người xưa có câu 'người tặng ta quả đào, ta đền bằng quả mận', chìa tay giúp đỡ lúc người khác hoạn nạn, duy trì sự gắn kết ấm áp và hòa hợp trong cộng đồng." },
    { ...chars.david, hanzi: "我明白了！这体现了中国文化重视集体和谐、顾及他人感受的厚德品格。", pinyin: "Wǒ míngbai le! Zhè tǐxiàn le Zhōngguó wénhuà zhòngshì jítǐ héxié, gùjí tārén gǎnshòu de hòudé pǐngé.", vi: "Em hiểu rồi ạ! Điều này phản ánh phẩm cách trọng sự hòa hợp tập thể, biết lắng nghe và trân trọng cảm xúc của người khác trong văn hóa Trung Hoa." }
  ],

  // BÀI 69: 现代家庭观念的变迁
  "jc_3_2_69": [
    { ...chars.tian, sectionTitle: "课文一：传统四世同堂到核心家庭 (Gia đình truyền thống đến hạt nhân hiện đại)", hanzi: "过去中国传统社会崇尚‘四世同堂’、大家族聚居，如今在大都市里，核心家庭和小家庭模式已成为主流。", pinyin: "Guòqù Zhōngguó chuántǒng shèhuì chóngshàng 'sì shì tóng táng', dà jiāzú jùjū, rújīn zài dà dūshì lǐ, héxīn jiātíng hé xiǎo jiātíng móshì yǐ chéngwéi zhǔliú.", vi: "Trước kia xã hội truyền thống Trung Quốc tôn sùng nếp sống 'tứ đại đồng đường', đại gia đình sum vầy cùng chung sống, ngày nay tại các đô thị lớn, mô hình gia đình hạt nhân và gia đình nhỏ đã trở thành dòng chảy chủ đạo." },
    { ...chars.edward, hanzi: "年轻人的婚恋观与孝道观念是否也发生了深刻改变？", pinyin: "Niánqīngrén de hūnliànguān yǔ xiàodào guānniàn shìfǒu yě fāshēng le shēnkè gǎibiàn?", vi: "Quan niệm hôn nhân và chữ hiếu của giới trẻ hiện nay liệu có những đổi thay sâu sắc không?" },
    { ...chars.wang, hanzi: "现代青年更加追求个人价值实现与平等沟通，但‘孝道’这一道德基因依然根深蒂固，只是表达方式由过去的朝夕奉养转变为高质量的精神陪伴与经济支持。", pinyin: "Xiàndài qīngnián gèngjiā zhuīqiú gèrén jiàzhí shíxiàn yǔ píngděng gōutōng, dàn 'xiàodào' zhè yí dàodé jīyīn yīrán gēnshēn-dìgù, zhǐshì biǎodá fāngshì yóu guòqù de zhāoxī fèngyǎng zhuǎnbiàn wéi gāo zhìliàng de jīngshén péibàn yǔ jīngjì zhīchí.", vi: "Thanh niên thời nay theo đuổi nhiều hơn sự khẳng định giá trị cá nhân và đối thoại bình đẳng, tuy nhiên gen đạo đức 'chữ Hiếu' vẫn bén rễ sâu xa, chỉ là phương thức biểu đạt từ chăm nom sớm tối xưa kia đã chuyển sang sự quan tâm tinh thần chất lượng cao và chu cấp kinh tế vững vàng." }
  ],

  // BÀI 70: 环境保护与绿色低碳发展
  "jc_3_2_70": [
    { ...chars.mike, sectionTitle: "课文一：生态文明与绿色出行 (Văn minh sinh thái & Đô thị xanh)", hanzi: "走在北京街头，我看到马路上到处都是绿牌的新能源汽车，共享单车也非常普及，空气质量比前几年有了翻天覆地的改善！", pinyin: "Zǒu zài Běijīng jiētóu, wǒ kàndào mǎlù shàng dàochù dōu shì lǜpái de xīnnéngyuán qìchē, gòngxiǎng dānchē yě fēicháng pǔjí, kōngqì zhìliàng bǐ qián jǐ nián yǒu le fāntiān-fùdì de gǎishàn!", vi: "Dạo bước trên đường phố Bắc Kinh, em thấy trên đường đầy ắp xe năng lượng mới biển số xanh, xe đạp công cộng cũng cực kỳ phổ biến, chất lượng không khí so với mấy năm trước đã đổi thay vượt bậc!" },
    { ...chars.zhang, hanzi: "中国正在大力贯彻‘绿水青山就是金山银山’的生态发展理念，推行碳达峰、碳中和目标，植树造林，保护生物多样性。", pinyin: "Zhōngguó zhèngzài dàlì guànchè 'lǜshuǐ qīngshān jiù shì jīnshān yínshān' de shēngtài fāzhǎn lǐniàn, tuīxíng tàndáfēng, tànzhōnghé mùbiāo, zhíshù zàolín, bǎohù shēngwù duōyàngxìng.", vi: "Trung Quốc đang ra sức quán triệt triết lý phát triển sinh thái 'Non xanh nước biếc chính là núi vàng núi bạc', đẩy mạnh mục tiêu đạt đỉnh carbon và trung hòa carbon, phủ xanh rừng và bảo tồn đa dạng sinh học." },
    { ...chars.wang, hanzi: "保护地球家园是全人类共同的使命，绿色低碳不仅是经济转型之路，更彰显了中国古人‘道法自然’的可持续发展智慧。", pinyin: "Bǎohù dìqiú jiāyuán shì quán rénlèi gòngtóng de shǐmìng, lǜsè dītàn bùjǐn shì jīngjì zhuǎnxíng zhī lù, gèng zhāngxiǎn le Zhōngguó gǔrén 'dàofǎ zìrán' de kěchíxù fāzhǎn zhìhuì.", vi: "Bảo vệ mái nhà chung Trái đất là sứ mệnh thiêng liêng của toàn nhân loại, phát triển xanh ít phát thải không chỉ là con đường chuyển dịch kinh tế, mà còn làm tỏa sáng trí tuệ phát triển bền vững 'Đạo thuận theo Tự nhiên' của cổ nhân Trung Hoa." }
  ],

  // BÀI 71: 现代科技与生活变革
  "jc_3_2_71": [
    { ...chars.mary, sectionTitle: "课文一：无现金社会与高铁速度 (Xã hội không tiền mặt & Tốc độ đường sắt cao tốc)", hanzi: "在中国生活实在太便利了！出门只要带一部智能手机，扫码支付、网上叫车、外卖点餐，几分钟内全部搞定！", pinyin: "Zài Zhōngguó shēnghuó shízài tài biànlì le! Chūmén zhǐyào dài yí bù zhìnéng shǒujī, sǎomǎ zhīfù, wǎngshang jiàochē, wàimài diǎncān, jǐ fēnzhōng nèi quánbù gǎodìng!", vi: "Sống ở Trung Quốc thực sự tiện lợi vô cùng! Ra khỏi cửa chỉ cần mang một chiếc điện thoại thông minh, quét mã thanh toán, gọi xe công nghệ, đặt đồ ăn giao tận nơi, mọi thứ hoàn tất trong vài phút!" },
    { ...chars.edward, hanzi: "不仅如此，中国的高铁网络四通八达，时速达三百五十公里，平稳得连一枚硬币立在窗台上都不会倒，真令人叹为观止！", pinyin: "Bùjǐn rúcǐ, Zhōngguó de gāotiě wǎngluò sìtōng-bādá, shísù dá sānbǎi wǔshí gōnglǐ, píngwěn de lián yì méi yìngbì lì zài chuāngtái shàng dōu bú huì dǎo, zhēn lìng rén tànwéiguānzhǐ!", vi: "Không những vậy, mạng lưới đường sắt cao tốc của Trung Quốc kết nối muôn phương, vận tốc đạt 350 km/h, êm ái đến mức dựng một đồng xu trên bậu cửa sổ cũng không hề nghiêng đổ, thật khiến người ta ngả mũ thán phục!" },
    { ...chars.wang, hanzi: "人工智能、量子计算、移动互联正在深刻重塑人类文明的形态，科技创新的最终目的，始终是造福人民的美好生活。", pinyin: "Réngōng zhìnéng, liàngzǐ jìsuàn, yídòng hùlián zhèngzài shēnkè chóngshù rénlèi wénmíng de xíngtài, kējì chuàngxīn de zuìzhōng mùdì, shǐzhōng shì zàofú rénmín de měihǎo shēnghuó.", vi: "Trí tuệ nhân tạo, tính toán lượng tử và internet di động đang tái định hình sâu sắc diện mạo văn minh nhân loại, đích đến cuối cùng của đổi mới sáng tạo công nghệ luôn là mang lại cuộc sống phồn vinh hạnh phúc cho người dân." }
  ],

  // BÀI 72: 传统美德与现代文明
  "jc_3_2_72": [
    { ...chars.li, sectionTitle: "课文一：古老美德的现代表达 (Đạo đức ngàn năm tỏa sáng thời đại mới)", hanzi: "中华文化崇尚‘仁、义、礼、智、信’五常美德，这些跨越千年的伦理规范在现代社会中如何焕发新的生机？", pinyin: "Zhōnghuá wénhuà chóngshàng 'rén, yì, lǐ, zhì, xìn' wǔ cháng měidé, zhèxiē kuàyuè qiānnián de lúnlǐ guīfàn zài xiàndài shèhuì zhōng rúhé huànfā xīn de shēngjī?", vi: "Văn hóa Trung Hoa tôn vinh năm đức tính ngũ thường 'Nhân, Nghĩa, Lễ, Trí, Tín', các chuẩn mực đạo đức vượt thời gian ngàn năm này đang bừng nở sức sống mới ra sao trong xã hội đương đại?" },
    { ...chars.zhang, hanzi: "‘仁者爱人’化作了当今无数青年的志愿服务与互助奉献；‘人无信不立’成为了现代商业信用与法治社会的核心基石。", pinyin: "'Rénzhě àirén' huàzuò le dāngjīn wúshù qīngnián de zhìyuàn fúwù yǔ hùzhù fèngxiàn; 'rén wú xìn bù lì' chéngwéi le xiàndài shāngyè xìnyòng yǔ fǎzhì shèhuì de héxīn jīshí.", vi: "'Kẻ nhân thương người' đã hóa thân thành các hoạt động thiện nguyện tương thân tương ái của vô vàn thanh niên; 'người không giữ chữ Tín ắt khó đứng vững' trở thành nền tảng cốt lõi của uy tín thương mại và xã hội pháp quyền hiện đại." },
    { ...chars.li, hanzi: "优秀传统文化是民族的精神命脉，古今交融、薪火相传，才能构建具有深厚人文底蕴的现代化精神文明。", pinyin: "Yōuxiù chuántǒng wénhuà shì mínzú de jīngshén mìngmài, gǔ-jīn jiāoróng, xīnhuǒ-xiāngchuán, cái néng gòujiàn jùyǒu shēnhòu rénwén dǐyùn de xiàndàihuà jīngshén wénmíng.", vi: "Văn hóa truyền thống ưu tú là cội nguồn huyết mạch tinh thần của một dân tộc, xưa nay giao hòa tiếp nối ngọn lửa thiêng, mới có thể kiến thiết một nền văn minh tinh thần hiện đại thấm đẫm chiều sâu nhân văn." }
  ],

  // BÀI 73: 汉语成语在现代写作中的运用
  "jc_3_2_73": [
    { ...chars.wang, sectionTitle: "课文一：言简意赅的语言魅力 (Sức hút ngôn ngữ súc tích ý nhị)", hanzi: "成语是汉语词汇的精华，四字之中往往凝练了数千年的历史智慧。在HSK6级高分写作中，恰当使用成语能起到画龙点睛的作用。", pinyin: "Chéngyǔ shì Hànyǔ cíhuì de jīnghuá, sì zì zhī zhōng wǎngwǎng níngliàn le shù qiān nián de lìshǐ zhìhuì. Zài HSK 6 jí gāofēn xiězuò zhōng, qiàdàng shǐyòng chéngyǔ néng qǐdào huà-lóng-diǎn-jīng de zuòyòng.", vi: "Thành ngữ là tinh hoa đúc kết của vốn từ vựng Hán ngữ, chỉ vọn vẹn trong bốn chữ mà cô đọng trí tuệ lịch sử mấy ngàn năm. Trong bài viết điểm cao của kỳ thi HSK 6, vận dụng thành ngữ chuẩn xác sẽ đóng vai trò điểm nhãn như rồng bay lên mây." },
    { ...chars.david, hanzi: "老师，运用成语时最需要注意什么？", pinyin: "Lǎoshī, yùnyòng chéngyǔ shí zuì xūyào zhùyì shénme?", vi: "Thưa thầy, khi sử dụng thành ngữ điều cần lưu tâm nhất là gì ạ?" },
    { ...chars.wang, hanzi: "切忌生搬硬套、望文生义。比如‘胸有成竹’、‘按图索骥’，必须准确掌握其褒贬色彩、语境搭配和语法功能，方能字字珠玑、游刃有余。", pinyin: "Qièjì shēngbān-yìngtào, wàngwén-shēngyì. Bǐrú 'xiōng yǒu chéng zhú', 'àn tú suǒ jì', bìxū zhǔnquè zhǎngwò qí bāobiǎn sècǎi, yǔjìng dāpèi hé yǔfǎ gōngnéng, fāng néng zìzì-zhūjī, yóurèn-yǒuyú.", vi: "Tuyệt đối tránh rập khuôn máy móc, nhìn mặt chữ suy đoán bừa nghĩa. Ví dụ như 'trong lòng đã có sẵn bức tranh cây trúc', 'theo tranh tìm ngựa', cần phải nắm chắc sắc thái khen chê, ngữ cảnh kết hợp và chức năng ngữ pháp, mới có thể gọt giũa lời hay ý đẹp, vận dụng nhẹ nhàng tự tại." }
  ],

  // BÀI 74: 中国古代建筑与天人合一智慧
  "jc_3_2_74": [
    { ...chars.li, sectionTitle: "课文一：木构榫卯与中轴对称 (Kết cấu mộng gỗ & Trục đối xứng)", hanzi: "北京故宫太和殿、天坛祈年殿展示了中国古建筑的巅峰造诣。古人不耗一颗铁钉，仅凭榫卯咬合就能让木构大殿历经数百年地震而巍然屹立！", pinyin: "Běijīng Gùgōng Tàihédiàn, Tiāntán Qíniándiàn zhǎnshì le Zhōngguó gǔ jiànzhù de diānfēng zàoyì. Gǔrén bù hào yì kē tiědīng, jǐn píng sǔnmǎo yǎohé jiù néng ràng mùgòu dàdiàn lìjīng shù bǎi nián dìzhèn ér wēirán-yìlì!", vi: "Điện Thái Hòa ở Cố Cung Bắc Kinh, điện Kỳ Niên ở Thiên Đàn thể hiện đỉnh cao nghệ thuật kiến trúc cổ đại Trung Hoa. Cổ nhân không dùng một chiếc đinh sắt, chỉ nhờ kỹ thuật mộng gỗ lồng ghép khít khao mà giúp các đại điện bằng gỗ sừng sững qua hàng trăm năm động đất phong ba!" },
    { ...chars.roland, hanzi: "故宫那条纵贯南北的壮美中轴线，秩序井然，体现了崇高庄严的礼乐规制与天地秩序。", pinyin: "Gùgōng nà tiáo zòngguàn nán-běi de zhuàngměi zhōngzhóuxiàn, zhìxù-jǐngrán, tǐxiàn le chónggāo zhuāngyán de lǐyuè guīzhì yǔ tiāndì zhìxù.", vi: "Trục giữa tráng lệ xuyên suốt nam bắc của Tử Cấm Thành trật tự ngăn nắp, thể hiện khuôn phép lễ nhạc trang nghiêm cùng trật tự của đất trời." },
    { ...chars.li, hanzi: "而苏州园林移步换景，顺应自然山水之势，巧妙融建筑于山林花木之间，体现了‘天人合一、道法自然’的东方美学精魂。", pinyin: "Ér Sūzhōu yuánlín yíbù-huànjǐng, shùnyìng zìrán shānshuǐ zhī shì, qiǎomiào róng jiànzhù yú shānlín huāmù zhījiān, tǐxiàn le 'tiānrén-héyī, dàofǎ-zìrán' de dōngfāng měixué jīnghún.", vi: "Trong khi đó lâm viên Tô Châu mỗi bước đổi một cảnh, thuận theo thế núi non sông nước tự nhiên, lồng ghép khéo léo kiến trúc giữa cây cỏ hoa lá, thể hiện linh hồn mỹ học phương Đông 'Thiên nhân hợp nhất, Đạo thuận tự nhiên'." }
  ],

  // BÀI 75: 跨文化交际中的误解与融通
  "jc_3_2_75": [
    { ...chars.mike, sectionTitle: "课文一：文化休克与化解之道 (Sốc văn hóa & Con đường hòa nhập)", hanzi: "刚来中国时，听到别人夸赞我，我习惯说‘谢谢’，但中国朋友却常谦逊地说‘哪里哪里’；别人给我夹菜，我起初也感到不太适应。", pinyin: "Gāng lái Zhōngguó shí, tīngdào biérén kuāzàn wǒ, wǒ xíguàn shuō 'xièxie', dàn Zhōngguó péngyou què cháng qiānxùn de shuō 'nǎlǐ nǎlǐ'; biérén gěi wǒ jiā cài, wǒ qǐchū yě gǎndào bú tài shìyìng.", vi: "Lúc mới đến Trung Quốc, nghe người khác khen ngợi mình quen nói 'cảm ơn', nhưng các bạn Trung Quốc lại khiêm tốn bảo 'đâu có đâu có'; người khác gắp thức ăn cho mình, thoạt đầu mình cũng thấy chưa quen lắm." },
    { ...chars.wang, hanzi: "这正是典型的跨文化交际差异。西方文化强调个体独立与直接表达，中国文化则崇尚含蓄谦和与热情关怀。", pinyin: "Zhè zhèng shì diǎnxíng de kuà-wénhuà jiāojì chāyì. Xīfāng wénhuà qiángdiào gètǐ dúlì yǔ zhíjiē biǎodá, Zhōngguó wénhuà zé chóngshàng hánxù qiānhé yǔ rèqíng guānhuái.", vi: "Đây chính là nét khác biệt điển hình trong giao lưu liên văn hóa. Văn hóa phương Tây đề cao tính độc lập của cá nhân và biểu đạt trực tiếp, còn văn hóa Trung Hoa lại chuộng sự khiêm nhường hàm súc và ân cần chu đáo." },
    { ...chars.mary, hanzi: "克服文化休克的最好办法是保持包容开放的心态，‘美美与共，天下大同’，在相互理解中发现彼此文化的光彩！", pinyin: "Kèfú wénhuà xiūkè de zuì hǎo bànfǎ shì bǎochí bāoróng kāifàng de xīntài, 'měi měi yǔ gòng, tiānxià dàtóng', zài xiānghù lǐjiě zhōng fāxiàn bǐcǐ wénhuà de guāngcǎi!", vi: "Cách tốt nhất để vượt qua cú sốc văn hóa là giữ tâm thế cởi mở bao dung, 'tôn vinh cái đẹp của nhau để cùng hòa hợp', trong sự thấu hiểu chân thành mà tỏa rạng nét đẹp tinh hoa của muôn nền văn hóa!" }
  ],

  // BÀI 76: 展望未来：全球化语境下的中文传播
  "jc_3_2_76": [
    { ...chars.li, sectionTitle: "课文一：中文连通世界 (Tiếng Trung kết nối thế giới)", hanzi: "今天，全球学习中文的人数已突破两亿。从古丝绸之路上的驼铃悠悠，到如今遍布五洲的中文热，中文正以前所未有的魅力走向世界舞台中央。", pinyin: "Jīntiān, quánqiú xuéxí zhōngwén de rénshù yǐ tūpò liǎng yì. Cóng gǔ sīchóuzhīlù shàng de tuólíng yōuyōu, dào rújīn biànbù wǔzhōu de zhōngwén rè, zhōngwén zhèng yǐ qiánsuǒwèiyǒu de mèilì zǒuxiàng shìjiè wǔtái zhōngyāng.", vi: "Ngày nay, số người học tiếng Trung trên toàn cầu đã vượt mốc 200 triệu người. Từ tiếng chuông lạc đà ngân nga trên con đường tơ lụa cổ xưa, cho đến làn sóng học tiếng Hán nở rộ khắp năm châu hiện tại, tiếng Trung đang với sức hút chưa từng có bước ra vũ đài trung tâm của thế giới." },
    { ...chars.mike, hanzi: "学好中文不仅让我们掌握了一门国际语言，更打开了理解东方文明深邃内涵的金色钥匙，搭建起民心相通的友谊之桥。", pinyin: "Xuéhǎo zhōngwén bùjǐn ràng wǒmen zhǎngwò le yì mén guójì yǔyán, gèng dǎkāi le lǐjiě dōngfāng wénmíng shēnsuì nèihán de jīnsè yàoshi, dājiàn qǐ mínxīn-xiāngtōng de yǒuyì zhī qiáo.", vi: "Học giỏi tiếng Trung không chỉ giúp chúng em nắm vững một ngôn ngữ quốc tế, mà còn mở ra chiếc chìa khóa vàng thấu hiểu nội hàm thâm sâu của nền văn minh phương Đông, bắc nên cây cầu hữu nghị kết nối triệu con tim." },
    { ...chars.wang, hanzi: "“海内存知己，天涯若比邻。”愿大家以中文为伴，多学一门外语，多看一个世界，多过一种丰盈精彩的人生！", pinyin: "\"Hǎi nèi cún zhījǐ, tiānyá ruò bǐlín.\" Yuàn dàjiā yǐ zhōngwén wéi bàn, duō xué yì mén wàiyǔ, duō kàn yí gè shìjiè, duō guò yì zhǒng fēngyíng jīngcǎi de rénshēng!", vi: "\"Bốn bể có bạn tri kỷ, chân trời góc biển cũng tựa như láng giềng kề bên.\" Chúc các em luôn lấy tiếng Trung làm người bạn tri âm tri kỷ: Học thêm một ngoại ngữ, ngắm nhìn thêm một thế giới, sống trọn thêm một cuộc đời tràn đầy ý nghĩa và rực rỡ huy hoàng!" }
  ]
};

let updatedCount = 0;
jiaocheng.lessons.forEach(lesson => {
  if (vol3Dialogues[lesson.id]) {
    lesson.dialogues = vol3Dialogues[lesson.id];
    updatedCount++;
  }
});

fs.writeFileSync(dataPath, JSON.stringify(jiaocheng, null, 2), 'utf8');
console.log(`Successfully updated ${updatedCount} lessons in Volume 3 (3-1 & 3-2) with authentic dialogues!`);
